style.css:
@-moz-document domain("character.ai") {
header.site-header {
    background-image: url("https://i.imgur.com/KmaQMz.png") !important;
    background-size: cover !important;
    background-position: center !important;
    min-height: 180px; /* adjust */
  }

  /* if header text is unreadable */
  header.site-header::after {
    content: "";
    display: block;
    height: 100%;
    width: 100%;
    background: rgba(0,0,0,0.25);
  }
}
